const b = $json.body;
if (!b || typeof b !== 'object' || Array.isArray(b)) throw new Error('Expected JSON body');
const keys = ['eventId','type','occurredAt','entryId','entryDate','level','score','correctionCount','wordCount'];
if (Object.keys(b).length !== keys.length || keys.some(k => !(k in b))) throw new Error('Unexpected contract');
if (b.type !== 'entry.created' || !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(b.eventId)) throw new Error('Invalid event');
if (typeof b.occurredAt !== 'string' || !Number.isFinite(Date.parse(b.occurredAt)) || !/^\d{4}-\d{2}-\d{2}T/.test(b.occurredAt)) throw new Error('Invalid timestamp');
if (typeof b.entryDate !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(b.entryDate) || !Number.isFinite(Date.parse(b.entryDate)) || new Date(b.entryDate).toISOString().slice(0,10) !== b.entryDate) throw new Error('Invalid date');
if (!['A1','A2','B1','B2','C1','C2'].includes(b.level)) throw new Error('Invalid level');
for (const k of ['entryId','score','correctionCount','wordCount']) if (!Number.isSafeInteger(b[k]) || b[k] < 0) throw new Error('Invalid numeric metric');
if (b.entryId < 1 || b.wordCount < 1 || b.score > 100 || b.correctionCount > 100000 || b.wordCount > 1000000) throw new Error('Out of range');
return {json: b};

