WITH inserted AS (
INSERT INTO diary_automation.entry_events (event_id, occurred_at, entry_id, entry_date, level, score, correction_count, word_count)
VALUES ($1::uuid, $2::timestamptz, $3::bigint, $4::date, $5, $6::integer, $7::integer, $8::integer)
ON CONFLICT (event_id) DO NOTHING RETURNING event_id
) SELECT true AS accepted, EXISTS (SELECT 1 FROM inserted) AS inserted;
